{"code": "import requests, re

files = {
 "1991": "Pepsi logo 1991.svg",
 "1998": "Pepsi (1998).svg",
 "2003": "Pepsi 2003.svg",
 "2006_stacked": "Pepsi (2006) stacked.svg",
}

for k,f in files.items():
    url = "https://commons.wikimedia.org/wiki/Special:FilePath/" + requests.utils.quote(f)
    try:
        r = requests.get(url, timeout=30, headers={"User-Agent":"Mozilla/5.0"})
        print("=====", k, f, r.status_code, len(r.text))
        txt = r.text
        # print viewBox and first 1500 chars
        m = re.search(r'viewBox="[^"]+"', txt)
        print("viewBox:", m.group(0) if m else None)
        print(txt[:800].replace("\n"," ")[:800])
    except Exception as e:
        print(k, "ERR", e)
"}

{"code": "import urllib.request, re, json

files = {
 "1991": "Pepsi logo 1991.svg",
 "1998": "Pepsi (1998).svg",
 "2003": "Pepsi 2003.svg",
 "2006_stacked": "Pepsi (2006) stacked.svg",
}

def fetch(f):
    url = "https://commons.wikimedia.org/wiki/Special:FilePath/" + urllib.parse.quote(f)
    req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0 (compatible; research)"})
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read().decode('utf-8', errors='ignore')

import urllib.parse
for k,f in files.items():
    try:
        txt = fetch(f)
        print("=====", k, f, len(txt))
        m = re.search(r'viewBox="[^"]+"', txt)
        print("viewBox:", m.group(0) if m else None)
        print(txt[:600].replace("\n", " "))
    except Exception as e:
        print(k, "ERR", repr(e))
"}

